            $fullName = trim(implode(' ', array_filter([
                $record['first_name'],
                $record['middle_name'],
                $record['last_name'],
                $record['extension_name'],
            ], fn ($value) => $value !== null && $value !== '')));

            $identity = [
                'first_name' => $record['first_name'],
                'middle_name' => $record['middle_name'],
                'last_name' => $record['last_name'],
                'extension_name' => $record['extension_name'],
                'barangay' => $record['barangay'],
                'municipality' => $record['municipality'],
            ];

            $existingByNumber = RegisteredProducer::query()
                ->where('rsbsa_number', $record['rsbsa_number'])
                ->first();
            $existingByIdentity = RegisteredProducer::query()
                ->where($identity)
                ->first();

            if ($existingByNumber && $existingByIdentity && $existingByNumber->registry_id !== $existingByIdentity->registry_id) {
                throw new \RuntimeException("Conflicting synthetic registry rows found for {$record['rsbsa_number']}.");
            }

            $existing = $existingByIdentity ?? $existingByNumber;

            if ($existing) {
                foreach ($identity as $field => $value) {
                    if ($existing->{$field} !== $value) {
                        throw new \RuntimeException("Synthetic registry reference {$record['rsbsa_number']} is assigned to a different identity.");
                    }
                }

                if ($existing->rsbsa_number !== $record['rsbsa_number']) {
                    $existing->update(['rsbsa_number' => $record['rsbsa_number']]);
                }

                continue;
            }

            RegisteredProducer::create(array_merge($identity, [
                'rsbsa_number' => $record['rsbsa_number'],
                'full_name' => $fullName,
                'name' => $fullName,
